import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.rm68tLg1.js";const u=JSON.parse('{"title":"How optionality is inferred","description":"","frontmatter":{},"headers":[],"relativePath":"learn/explanation/optionality.md","filePath":"learn/explanation/optionality.md","lastUpdated":1786299590000}'),s={name:"learn/explanation/optionality.md"};function n(r,e,d,l,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-optionality-is-inferred" tabindex="-1">How optionality is inferred <a class="header-anchor" href="#how-optionality-is-inferred" aria-label="Permalink to &quot;How optionality is inferred&quot;">​</a></h1><p>Whether a parameter is required, optional, or defaulted is not something you declare twice in Argot. You say it once, and the property&#39;s type follows — or, in the annotation style, the type says it and Argot follows. Understanding which direction the inference runs explains most of the surprises.</p><h2 id="in-the-delegate-style-the-builder-decides-the-type" tabindex="-1">In the delegate style, the builder decides the type <a class="header-anchor" href="#in-the-delegate-style-the-builder-decides-the-type" aria-label="Permalink to &quot;In the delegate style, the builder decides the type&quot;">​</a></h2><p>A bare <code>option(...)</code> produces a nullable property. Each terminal call changes what you get:</p><table tabindex="0"><thead><tr><th>You write</th><th>Property type</th><th>Absent means</th></tr></thead><tbody><tr><td><code>option(&quot;--x&quot;)</code></td><td><code>String?</code></td><td><code>null</code></td></tr><tr><td><code>option(&quot;--x&quot;).required()</code></td><td><code>String</code></td><td>a parse error</td></tr><tr><td><code>option(&quot;--x&quot;).default(&quot;v&quot;)</code></td><td><code>String</code></td><td><code>&quot;v&quot;</code></td></tr><tr><td><code>option(&quot;--x&quot;).multiple()</code></td><td><code>List&lt;String&gt;</code></td><td>empty list</td></tr><tr><td><code>option(&quot;--x&quot;).multiple().required()</code></td><td><code>List&lt;String&gt;</code></td><td>a parse error</td></tr><tr><td><code>argument()</code></td><td><code>String</code></td><td>a parse error</td></tr><tr><td><code>argument().optional()</code></td><td><code>String?</code></td><td><code>null</code></td></tr></tbody></table><p>This is why the builder returns a different type at each step rather than the same one: <code>.default(v)</code> returns a <code>RequiredOptionBuilder&lt;T&gt;</code>, whose <code>provideDelegate</code> produces a non-null property. The nullability of your property is a consequence of the call chain, so the two cannot disagree. You never annotate a type and hope the library agrees with you.</p><p>The ordering rule falls out of the same idea. <code>.int()</code> says what one value is; <code>.default(1)</code> says what to use when there is none. Writing <code>.default(&quot;1&quot;).int()</code> would not compile, because after <code>.default(...)</code> there is no <code>.int()</code> to call.</p><h2 id="in-the-annotation-style-the-type-decides" tabindex="-1">In the annotation style, the type decides <a class="header-anchor" href="#in-the-annotation-style-the-type-decides" aria-label="Permalink to &quot;In the annotation style, the type decides&quot;">​</a></h2><p>The processor reads the constructor parameter and infers:</p><ul><li><strong>A nullable type is optional.</strong> <code>val host: String?</code> resolves to <code>null</code> when the option is absent.</li><li><strong>A non-null type with no <code>default</code> is required.</strong> <code>val port: Int</code> must be supplied.</li><li><strong>A non-null type with <code>default = &quot;...&quot;</code> is optional.</strong> The string is run through the same converter the parameter&#39;s type selects, so <code>default = &quot;8080&quot;</code> on an <code>Int</code> becomes <code>8080</code>.</li><li><strong>A <code>List&lt;T&gt;</code> is repeatable and never required.</strong> Absent means an empty list. A <code>List</code> cannot carry a <code>default</code>, and saying so is a compile error rather than a silently ignored annotation.</li></ul><h2 id="what-the-processor-cannot-see" tabindex="-1">What the processor cannot see <a class="header-anchor" href="#what-the-processor-cannot-see" aria-label="Permalink to &quot;What the processor cannot see&quot;">​</a></h2><p>This produces the one error message that looks like a bug.</p><p>KSP tells the processor <em>that</em> a constructor parameter has a Kotlin default, but not what that default is. Default values are expressions, and the processor has the declaration, not the compiled expression. So this:</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes argot-light argot-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0F8A6A;--shiki-dark:#4CC4A0;">@Option</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">(names </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">=</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;"> [</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;">&quot;--port&quot;</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">], help </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">=</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;"> &quot;Port&quot;</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">) </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">val</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;"> port: </span><span style="--shiki-light:#0F8A6A;--shiki-dark:#4CC4A0;">Int</span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;"> =</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;"> 8080</span></span></code></pre></div><p>is rejected, with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes argot-light argot-dark vp-code" tabindex="0"><code><span class="line"><span>@Option &#39;port&#39; has a Kotlin default that Argot cannot read.</span></span>
<span class="line"><span>Add default=&quot;...&quot; to the annotation, or make the parameter type nullable.</span></span></code></pre></div><p>The alternative would have been to ignore the Kotlin default and treat <code>port</code> as required — which compiles, runs, and then fails at the command line for a user who reasonably expected 8080 to be the default. Refusing to build is the less surprising of the two.</p><p>Write it as the processor can read it:</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes argot-light argot-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0F8A6A;--shiki-dark:#4CC4A0;">@Option</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">(names </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">=</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;"> [</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;">&quot;--port&quot;</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">], help </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">=</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;"> &quot;Port&quot;</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">, default </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">=</span><span style="--shiki-light:#B4611B;--shiki-dark:#DC9A5E;"> &quot;8080&quot;</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;">) </span><span style="--shiki-light:#5B4BEA;--shiki-dark:#A79BFF;">val</span><span style="--shiki-light:#3D3B45;--shiki-dark:#D6D4DE;"> port: </span><span style="--shiki-light:#0F8A6A;--shiki-dark:#4CC4A0;">Int</span></span></code></pre></div><h2 id="why-not-just-read-the-kotlin-default-anyway" tabindex="-1">Why not just read the Kotlin default anyway <a class="header-anchor" href="#why-not-just-read-the-kotlin-default-anyway" aria-label="Permalink to &quot;Why not just read the Kotlin default anyway&quot;">​</a></h2><p>Because the parser has to be able to <em>report</em> the default, not only apply it. <code>--help</code> shows <code>(default: 8080)</code>, which means the value must be available to <code>CommandSpec</code> at the point the help is rendered — before your constructor is called, and without evaluating an arbitrary expression that might read a file or the clock. A string in the annotation is a value the processor can both pass through the converter and print.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../how-to/optional-positionals">Make a positional argument optional</a> for the practical recipe.</li><li><a href="/docs/latest/api/org.draftcode.argot/OptionBuilder"><code>OptionBuilder</code></a> for the full chain of terminal calls.</li></ul>`,23)])])}const k=t(s,[["render",n]]);export{u as __pageData,k as default};
